<?php
require_once __DIR__ . '/../config/security.php';
ems_start_secure_session();
require_once __DIR__ . '/../config/db.php';

if (!isset($_SESSION['employee_id'])) { header('Location: ../index.php'); exit; }
$employeeId = (int)$_SESSION['employee_id'];
$employeeName = $_SESSION['employee_name'] ?? 'Employee';

$message='';$messageType='success';
if($_SERVER['REQUEST_METHOD']==='POST'){
 ems_verify_csrf();$action=$_POST['action']??'';
 try{
  if($action==='submit'){
   $recipientId=(int)($_POST['recipient_id']??0);$campaignId=(int)($_POST['campaign_id']??0);$date=$_POST['adjustment_date']??'';$type=trim($_POST['adjustment_type']??'');$hours=(int)($_POST['adjustment_hours']??0);$minutes=(int)($_POST['adjustment_minutes']??0);$seconds=(int)($_POST['adjustment_seconds']??0);$time=sprintf('%02d:%02d:%02d',$hours,$minutes,$seconds);$category=trim($_POST['reason_category']??'');$subcategory=trim($_POST['reason_subcategory']??'');$reason=trim($_POST['reason']??'');
   if(!$recipientId||$recipientId===$employeeId||!$campaignId||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!in_array($type,['Login','Withdrawal'],true)||$hours<0||$hours>99||$minutes<0||$minutes>59||$seconds<0||$seconds>59||($hours+$minutes+$seconds)===0||$category===''||$reason==='')throw new RuntimeException('Please complete all required fields and enter a valid H:M:S duration.');
   $recipientCheck=$conn->prepare("SELECT full_name FROM employees WHERE id=? AND is_active=1 AND status='Active' LIMIT 1");$recipientCheck->bind_param('i',$recipientId);$recipientCheck->execute();$recipient=$recipientCheck->get_result()->fetch_assoc();if(!$recipient)throw new RuntimeException('Selected employee is not available.');
   $requestNo='MIS-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));
   $s=$conn->prepare('INSERT INTO mis_adjustments(request_no,employee_id,recipient_id,campaign_id,adjustment_date,adjustment_type,adjustment_time,reason_category,reason_subcategory,reason) VALUES(?,?,?,?,?,?,?,?,?,?)');
   $s->bind_param('siiissssss',$requestNo,$employeeId,$recipientId,$campaignId,$date,$type,$time,$category,$subcategory,$reason);$s->execute();
   $message='MIS adjustment sent to '.$recipient['full_name'].'.';
  }elseif(in_array($action,['approve','reject'],true)){
   $id=(int)($_POST['id']??0);$status=$action==='approve'?'Approved':'Rejected';$comment=trim($_POST['comment']??'');
   $s=$conn->prepare("UPDATE mis_adjustments SET status=?,approver_comment=?,decided_at=NOW() WHERE id=? AND recipient_id=? AND status='Pending'");$s->bind_param('ssii',$status,$comment,$id,$employeeId);$s->execute();if($s->affected_rows!==1)throw new RuntimeException('Request was already processed or is not assigned to you.');$message='Request '.$status.'.';
  }elseif($action==='cancel'){$id=(int)($_POST['id']??0);$s=$conn->prepare("UPDATE mis_adjustments SET status='Cancelled' WHERE id=? AND employee_id=? AND status='Pending'");$s->bind_param('ii',$id,$employeeId);$s->execute();if($s->affected_rows!==1)throw new RuntimeException('Request cannot be cancelled.');$message='Request cancelled.';}
 }catch(Throwable $e){$message=$e->getMessage();$messageType='danger';}
}

$campaigns=$conn->query('SELECT id,name FROM performance_campaigns WHERE is_active=1 ORDER BY name')->fetch_all(MYSQLI_ASSOC);
$recipientsStmt=$conn->prepare("SELECT id,employee_id,full_name,role,designation FROM employees WHERE id<>? AND is_active=1 AND status='Active' ORDER BY full_name");$recipientsStmt->bind_param('i',$employeeId);$recipientsStmt->execute();$recipients=$recipientsStmt->get_result()->fetch_all(MYSQLI_ASSOC);
$sentStmt=$conn->prepare('SELECT m.*,c.name campaign_name,r.full_name recipient_name FROM mis_adjustments m LEFT JOIN performance_campaigns c ON c.id=m.campaign_id JOIN employees r ON r.id=m.recipient_id WHERE m.employee_id=? ORDER BY m.id DESC');$sentStmt->bind_param('i',$employeeId);$sentStmt->execute();$sent=$sentStmt->get_result()->fetch_all(MYSQLI_ASSOC);
$receivedStmt=$conn->prepare('SELECT m.*,c.name campaign_name,e.full_name employee_name,e.employee_id employee_code FROM mis_adjustments m LEFT JOIN performance_campaigns c ON c.id=m.campaign_id JOIN employees e ON e.id=m.employee_id WHERE m.recipient_id=? ORDER BY m.id DESC');$receivedStmt->bind_param('i',$employeeId);$receivedStmt->execute();$received=$receivedStmt->get_result()->fetch_all(MYSQLI_ASSOC);
function misBadge(string $status):string{return match($status){'Approved'=>'success','Rejected'=>'danger','Cancelled'=>'secondary',default=>'warning'};}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MIS Adjustments</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css" rel="stylesheet"><style>
body{background:#f4f7fb;font-family:Inter,Segoe UI,sans-serif;color:#1e293b}.top{background:linear-gradient(125deg,#163a70,#2563eb 70%,#06b6d4);color:#fff;padding:22px 0}.wrap{max-width:1400px}.card{border:1px solid #dbe4f0;border-radius:16px;box-shadow:0 7px 22px #0f172a0f}.form-control,.form-select{border-radius:10px;min-height:42px}.table th{font-size:11px;text-transform:uppercase;color:#64748b;background:#f8fafc;white-space:nowrap}.table td{font-size:13px;vertical-align:middle}.senior{background:#eff6ff;border:1px solid #bfdbfe;border-radius:12px;padding:12px}.nav-pills .nav-link{border-radius:10px;font-weight:600}.empty{padding:35px;text-align:center;color:#94a3b8}.duration-fields{display:grid;grid-template-columns:1fr auto 1fr auto 1fr;align-items:center;gap:6px}.duration-fields span{font-weight:700;color:#64748b}.duration-fields input{text-align:center;padding-left:5px;padding-right:5px}
</style></head><body><header class="top"><div class="container-fluid wrap d-flex justify-content-between align-items-center"><div><h3 class="mb-1"><i class="fa fa-sliders me-2"></i>MIS Adjustments</h3><small class="opacity-75">Send Login or Withdrawal adjustments to any employee</small></div><a href="dashboard.php" class="btn btn-light"><i class="fa fa-arrow-left me-1"></i> Dashboard</a></div></header><main class="container-fluid wrap py-4">
<?php if($message):?><div class="alert alert-<?=$messageType?> alert-dismissible"><?=htmlspecialchars($message)?><button class="btn-close" type="button" onclick="this.parentElement.remove()"></button></div><?php endif;?>
<div class="row g-4"><div class="col-lg-5"><div class="card p-4"><h5><i class="fa fa-paper-plane text-primary me-2"></i>New MIS Adjustment</h5><p class="text-muted small mb-3">Login ya Withdrawal adjustment kisi bhi active employee ko send karein.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(ems_csrf_token())?>"><input type="hidden" name="action" value="submit"><div class="row g-3"><div class="col-12"><label class="form-label">Send To Employee *</label><select name="recipient_id" class="form-select" required><option value="">Select Employee</option><?php foreach($recipients as $person):?><option value="<?=$person['id']?>"><?=htmlspecialchars($person['employee_id'].' - '.$person['full_name'].' - '.($person['designation']?:$person['role']))?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Campaign *</label><select name="campaign_id" class="form-select" required><option value="">Select Campaign</option><?php foreach($campaigns as $c):?><option value="<?=$c['id']?>"><?=htmlspecialchars($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Adjustment Date *</label><input type="date" name="adjustment_date" value="<?=date('Y-m-d')?>" class="form-control" required></div><div class="col-md-6"><label class="form-label">Adjustment Type *</label><select name="adjustment_type" class="form-select" required><option value="">Select Type</option><option>Login</option><option>Withdrawal</option></select></div><div class="col-md-6"><label class="form-label">Adjustment Duration (H:M:S) *</label><div class="duration-fields"><select name="adjustment_hours" class="form-select" aria-label="Hours"><?php for($i=0;$i<=99;$i++):?><option value="<?=$i?>"><?=str_pad((string)$i,2,'0',STR_PAD_LEFT)?></option><?php endfor;?></select><span>:</span><select name="adjustment_minutes" class="form-select" aria-label="Minutes"><?php for($i=0;$i<=59;$i++):?><option value="<?=$i?>"><?=str_pad((string)$i,2,'0',STR_PAD_LEFT)?></option><?php endfor;?></select><span>:</span><select name="adjustment_seconds" class="form-select" aria-label="Seconds"><?php for($i=0;$i<=59;$i++):?><option value="<?=$i?>"><?=str_pad((string)$i,2,'0',STR_PAD_LEFT)?></option><?php endfor;?></select></div><small class="text-muted">Hours : Minutes : Seconds</small></div><div class="col-md-6"><label class="form-label">Reason Category *</label><select name="reason_category" class="form-select" required><option value="">Select Category</option><option>Technical Issue</option><option>General</option><option>System Issue</option><option>Operational</option><option>Other</option></select></div><div class="col-md-6"><label class="form-label">Reason SubCategory</label><input name="reason_subcategory" class="form-control" placeholder="e.g. System"></div><div class="col-12"><label class="form-label">Reason *</label><textarea name="reason" class="form-control" rows="3" required></textarea></div><div class="col-12"><button class="btn btn-primary px-4"><i class="fa fa-paper-plane me-1"></i> Send Adjustment</button></div></div></form></div></div>
<div class="col-lg-7"><div class="card p-3"><ul class="nav nav-pills mb-3" role="tablist"><li class="nav-item"><button class="nav-link active" data-bs-toggle="pill" data-bs-target="#sent">My Requests (<?=count($sent)?>)</button></li><li class="nav-item"><button class="nav-link" data-bs-toggle="pill" data-bs-target="#received">Received Requests (<?=count($received)?>)</button></li></ul><div class="tab-content"><div class="tab-pane fade show active" id="sent"><div class="table-responsive"><table class="table"><thead><tr><th>Request</th><th>Campaign</th><th>Date / Duration</th><th>Sent To</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($sent as $row):?><tr><td><strong><?=htmlspecialchars($row['request_no'])?></strong><div class="text-muted"><?=htmlspecialchars($row['adjustment_type'])?></div></td><td><?=htmlspecialchars($row['campaign_name']??'-')?></td><td><?=date('d M Y',strtotime($row['adjustment_date']))?><div><strong><?=htmlspecialchars($row['adjustment_time'])?></strong> H:M:S</div></td><td><?=htmlspecialchars($row['recipient_name'])?></td><td><span class="badge text-bg-<?=misBadge($row['status'])?>"><?=$row['status']?></span><?php if($row['approver_comment']):?><div class="small mt-1"><?=htmlspecialchars($row['approver_comment'])?></div><?php endif;?></td><td><?php if($row['status']==='Pending'):?><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(ems_csrf_token())?>"><input type="hidden" name="action" value="cancel"><input type="hidden" name="id" value="<?=$row['id']?>"><button class="btn btn-sm btn-outline-danger">Cancel</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$sent):?><tr><td colspan="6" class="empty">No requests sent yet.</td></tr><?php endif;?></tbody></table></div></div>
<div class="tab-pane fade" id="received"><div class="table-responsive"><table class="table"><thead><tr><th>Employee</th><th>Campaign</th><th>Type / Duration</th><th>Reason</th><th>Status / Action</th></tr></thead><tbody><?php foreach($received as $row):?><tr><td><strong><?=htmlspecialchars($row['employee_name'])?></strong><div class="text-muted"><?=htmlspecialchars($row['employee_code'])?></div></td><td><?=htmlspecialchars($row['campaign_name']??'-')?></td><td><?=htmlspecialchars($row['adjustment_type'])?><div><?=date('d M Y',strtotime($row['adjustment_date']))?> · <strong><?=htmlspecialchars($row['adjustment_time'])?></strong> H:M:S</div></td><td style="min-width:190px"><strong><?=htmlspecialchars($row['reason_category'])?></strong><div><?=htmlspecialchars($row['reason'])?></div></td><td style="min-width:240px"><span class="badge text-bg-<?=misBadge($row['status'])?>"><?=$row['status']?></span><?php if($row['status']==='Pending'):?><form method="post" class="mt-2"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(ems_csrf_token())?>"><input type="hidden" name="id" value="<?=$row['id']?>"><input name="comment" class="form-control form-control-sm mb-2" placeholder="Comment"><button name="action" value="approve" class="btn btn-sm btn-success me-1">Approve</button><button name="action" value="reject" class="btn btn-sm btn-danger">Reject</button></form><?php elseif($row['approver_comment']):?><div class="small mt-1"><?=htmlspecialchars($row['approver_comment'])?></div><?php endif;?></td></tr><?php endforeach;?><?php if(!$received):?><tr><td colspan="5" class="empty">No requests received.</td></tr><?php endif;?></tbody></table></div></div></div></div></div></div></main><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>
